	// Result items carry the documented fields.
	items := out["instances"].([]any)
	first := items[0].(map[string]any)
	for _, key := range []string{"instance_id", "address", "healthy", "weight", "heartbeat_at"} {
		if _, ok := first[key]; !ok {
